import torch, math, copy
import torch.nn as nn
w=torch.load('weights.pt',map_location='cpu',weights_only=False)
d=torch.load('dataset.pt',map_location='cpu',weights_only=False)
src,tgt=d['src_sequences'],d['tgt_sequences']

class PositionalEncoding(nn.Module):
    def __init__(self, d_model, max_len=5000):
        super().__init__()
        pe=torch.zeros(max_len,d_model)
        position=torch.arange(0,max_len,dtype=torch.float).unsqueeze(1)
        div_term=torch.exp(torch.arange(0,d_model,2).float()*(-math.log(10000.0)/d_model))
        pe[:,0::2]=torch.sin(position*div_term)
        pe[:,1::2]=torch.cos(position*div_term)
        self.register_buffer('pe',pe.unsqueeze(0))
    def forward(self,x):
        return x+self.pe[:,:x.size(1)]

class M(nn.Module):
    def __init__(self, batch_first=True, sqrt=False, mask=False):
        super().__init__()
        self.batch_first=batch_first; self.sqrt=sqrt; self.mask=mask
        self.embedding=nn.Linear(64,128)
        self.pos_encoder=PositionalEncoding(128)
        self.transformer_encoder=nn.TransformerEncoder(nn.TransformerEncoderLayer(128,8,256,dropout=0.0,batch_first=batch_first),3)
        self.transformer_decoder=nn.TransformerDecoder(nn.TransformerDecoderLayer(128,8,256,dropout=0.0,batch_first=batch_first),1)
        self.output_layer=nn.Linear(128,64)
    def forward(self,src,tgt):
        if self.sqrt:
            src=self.embedding(src)*math.sqrt(128); tgt=self.embedding(tgt)*math.sqrt(128)
        else:
            src=self.embedding(src); tgt=self.embedding(tgt)
        src=self.pos_encoder(src); tgt=self.pos_encoder(tgt)
        memory=self.transformer_encoder(src)
        if self.mask:
            L=tgt.size(1); m=torch.triu(torch.ones(L,L,dtype=torch.bool),diagonal=1)
            out=self.transformer_decoder(tgt,memory,tgt_mask=m)
        else:
            out=self.transformer_decoder(tgt,memory)
        return self.output_layer(out)

for bf in [True,False]:
  for sq in [False,True]:
    for mk in [False,True]:
      try:
        m=M(bf,sq,mk); m.load_state_dict(w); m.eval()
        with torch.no_grad():
          if bf: out=m(src,tgt)
          else: out=m(src.transpose(0,1),tgt.transpose(0,1)).transpose(0,1)
          loss=nn.functional.mse_loss(out,tgt)
        print(bf,sq,mk,loss.item())
      except Exception as e:
        print('err',bf,sq,mk,e)
